// Test: GET /api/v3/account
const timestamp = Date.now();
const queryString = `timestamp=${timestamp}`;
const signature = CryptoJS.HmacSHA256(queryString, binance.secretKey).toString();
const url = `${binance.baseUrl}/api/v3/account?${queryString}&signature=${signature}`;

return [{
  json: {
    test: 'account_info',
    url,
    headers: { 'X-MBX-APIKEY': binance.apiKey },
    timestamp,
    queryString,
    signature
  }
}];

const staticData = $getWorkflowStaticData('global');
const price = parseFloat($input.first().json.price);

if (!staticData.priceHistory_B) staticData.priceHistory_B = [];
staticData.priceHistory_B.push(price);
if (staticData.priceHistory_B.length > 210)
  staticData.priceHistory_B = staticData.priceHistory_B.slice(-210);

const prices = staticData.priceHistory_B;
const n = prices.length;

// BB20
const bbReady = n >= 20;
let bbMid=0, bbUpper=0, bbLower=0, zscore=0;
if (bbReady) {
  const sl = prices.slice(-20);
  bbMid = sl.reduce((a,b)=>a+b,0)/20;
  const variance = sl.reduce((s,p)=>s+Math.pow(p-bbMid,2),0)/20;
  const std = Math.sqrt(variance);
  bbUpper = bbMid + 2*std;
  bbLower = bbMid - 2*std;
  zscore  = std > 0 ? (price - bbMid) / std : 0;
}

// EMA200 (filtre tendance)
const ema200Ready = n >= 200;
const ema200 = ema200Ready ? prices.slice(-200).reduce((a,b)=>a+b,0)/200 : null;
const bullMarket = ema200Ready ? price > ema200 : true;
const bearMarket = ema200Ready ? price < ema200 : true;

// RSI14
let rsi = 50;
if (n >= 15) {
  const p = prices.slice(-15);
  let gains=0, losses=0;
  for (let i=1;i<14;i++) {
    const chg = p[i]-p[i-1];
    if (chg>0) gains+=chg; else losses+=Math.abs(chg);
  }
  const ag=gains/14, al=losses/14;
  rsi = al===0 ? 100 : 100-(100/(1+ag/al));
}

const signalLong  = bbReady && zscore <= -2.2 && rsi <= 40  && bullMarket;
const signalShort = bbReady && zscore >=  2.2 && rsi >= 70  && bearMarket;

return [{ json: {
  strategie: 'B_MR4h',
  prix_actuel: price,
  bb_mid:   bbReady ? bbMid.toFixed(2)   : null,
  bb_upper: bbReady ? bbUpper.toFixed(2) : null,
  bb_lower: bbReady ? bbLower.toFixed(2) : null,
  zscore:   bbReady ? zscore.toFixed(3)  : null,
  rsi_14:   rsi.toFixed(2),
  bb_ready: bbReady,
  data_points: n,
  signal_long:  signalLong,
  signal_short: signalShort,
  sl_long:  bbReady ? (price * 0.94).toFixed(2) : null,
  tp_long:  bbReady ? bbUpper.toFixed(2)         : null,
  sl_short: bbReady ? (price * 1.06).toFixed(2)  : null,
  tp_short: bbReady ? bbLower.toFixed(2)          : null,
  timestamp: new Date().toISOString()
}}];

