const staticData = $getWorkflowStaticData('global');
const o = $input.first().json;

if (staticData.simulation_dca) {
  return [{ json: {
    orderId:     'DCA_SIM_' + Date.now(),
    symbol:      'BTCUSDT',
    side:        'BUY',
    executedQty: o.quantity.toString(),
    cummulativeQuoteQty: o.montantUSDT.toString(),
    fills:       [{ price: o.btcPrice.toString(), qty: o.quantity.toString() }],
    simulation:  true
  }}];
}

const r = await $helpers.httpRequest({
  method:  'POST',
  url:     o.url + '?' + o.queryString,
  headers: o.headers
});
return [{ json: r }];

const staticData = $getWorkflowStaticData('global');
const order   = $input.first().json;
const pending = staticData.pendingDCA;

// Sécurité : si pendingDCA est absent → STOP proprement
if (!pending) {
  return [{
    json: {
      error: true,
      message: "❌ ERREUR : pendingDCA est manquant — Prepare DCA Order n'a pas créé les données.",
      debug_order: order
    }
  }];
}

const execPrice = parseFloat(order.fills?.[0]?.price || pending.price);
const execQty   = parseFloat(order.executedQty || pending.quantity);
const montantUSDT = parseFloat(pending.montantUSDT);

// Cumulatif dans staticData (pour calcul avg_price)
if (!staticData.dcaSummary) staticData.dcaSummary = { totalBTC: 0, totalUSDT: 0, count: 0 };
staticData.dcaSummary.totalBTC   += execQty;
staticData.dcaSummary.totalUSDT  += montantUSDT;
staticData.dcaSummary.count      += 1;

const totalBTC  = staticData.dcaSummary.totalBTC;
const totalUSDT = staticData.dcaSummary.totalUSDT;
const avgPrice  = totalUSDT / totalBTC;

// Valeur actuelle en EUR
const valeurEUR = totalBTC * execPrice / 1.08;
const pnlEUR    = valeurEUR - (totalUSDT / 1.08);
const pnlPct    = ((valeurEUR - totalUSDT/1.08) / (totalUSDT/1.08)) * 100;

// Valeur actuelle en USD (pour Telegram)
const currentValueUSD = totalBTC * execPrice;
const pnlUSD = currentValueUSD - totalUSDT;

delete staticData.pendingDCA;

return [{
  json: {
    // Champs PostgreSQL
    montant_eur:   parseFloat((montantUSDT / 1.08).toFixed(2)),
    montant_usdt:  montantUSDT,
    btc_price:     execPrice,
    btc_quantity:  execQty,
    total_btc:     parseFloat(totalBTC.toFixed(8)),
    avg_price:     parseFloat(avgPrice.toFixed(2)),
    valeur_eur:    parseFloat(valeurEUR.toFixed(2)),
    pnl_eur:       parseFloat(pnlEUR.toFixed(2)),
    pnl_pct:       parseFloat(pnlPct.toFixed(4)),
    simulation:    staticData.simulation_dca !== false,

    // Champs Notify DCA
    btcPrice:      execPrice.toFixed(2),
    quantityBTC:   execQty.toFixed(8),
    montantUSDT:   montantUSDT.toFixed(2),
    totalBTC:      totalBTC.toFixed(8),
    totalSpent:    totalUSDT.toFixed(2),
    avgBuyPrice:   avgPrice.toFixed(2),
    currentValue:  currentValueUSD.toFixed(2),
    pnlUSD:        pnlUSD.toFixed(2),
    pnlPct:        pnlPct.toFixed(2),
    orderId:       order.orderId
  }
}];

