    ...$node['Prepare Entry Order'].json,
    quantity: qty,
    montantUSDT,
    leverage: leverage,
    riskPct: riskPct,
    maxLossUSD: parseFloat(maxLoss.toFixed(4)),
    sl_distance: parseFloat(slDistance.toFixed(2)),
