const closes = items.map(c => parseFloat(c.json.close));
const ema = (data, period) => { const k = 2 / (period + 1); let v = data[0]; for (let i = 1; i < data.length; i++) v = data[i] * k + v * (1 - k); return v; };
const ema9_4h = ema(closes, 9);
const ema26_4h = ema(closes, 26);
return [{ json: { ema9_4h: parseFloat(ema9_4h.toFixed(2)), ema26_4h: parseFloat(ema26_4h.toFixed(2)), trend4hUp: ema9_4h > ema26_4h, trend4hDown: ema9_4h < ema26_4h } }];

