    const bePrice = parseFloat((entryPrice * 1.0002).toFixed(2));
    if (bePrice > slPrice) {
      newSlPrice = bePrice;
      breakEvenTriggered = true;
    }
  }
} else {
  // BE_SELL : quand +0.12% atteint → SL remonte à 0.00% (entry)
  const unrealizedPnlPct = ((entryPrice - currentPrice) / entryPrice) * 100;
  if (unrealizedPnlPct >= 0.12) {
    const bePrice = parseFloat(entryPrice.toFixed(2));
    if (bePrice < slPrice) {
      newSlPrice = bePrice;
      breakEvenTriggered = true;
    }
  }
}

