const entryPrice = pos.entry_price;
const tpPrice = pos.tp_price;
let slPrice = pos.sl_price;
const direction = pos.direction;
const isBuy = direction === 'BUY' || direction === 'LONG';

// Variation % selon direction
const variationPct = isBuy
  ? ((currentPrice - entryPrice) / entryPrice) * 100
  : ((entryPrice - currentPrice) / entryPrice) * 100;

// === BREAK-EVEN DYNAMIQUE ===
let breakEvenTriggered = false;
let newSlPrice = slPrice;

if (isBuy) {
  // BE_LONG : quand +0.20% atteint → SL remonte à +0.02%
  const unrealizedPnlPct = ((currentPrice - entryPrice) / entryPrice) * 100;
  if (unrealizedPnlPct >= 0.20) {
    const bePrice = parseFloat((entryPrice * 1.0002).toFixed(2));
    if (bePrice > slPrice) {
      newSlPrice = bePrice;
      breakEvenTriggered = true;
    }
  }
} else {
  // BE_SELL : quand +0.12% atteint → SL remonte à 0.00% (entry)
  const unrealizedPnlPct = ((entryPrice - currentPrice) / entryPrice) * 100;
  if (unrealizedPnlPct >= 0.12) {
    const bePrice = parseFloat(entryPrice.toFixed(2));
    if (bePrice < slPrice) {
      newSlPrice = bePrice;
      breakEvenTriggered = true;
    }
  }
}

// Utilise le nouveau SL (break-even ou original)
const effectiveSlPrice = newSlPrice;

let shouldClose = false;
let reason = '';

// TP
if (isBuy && currentPrice >= tpPrice) { shouldClose = true; reason = 'TP atteint'; }
else if (!isBuy && currentPrice <= tpPrice) { shouldClose = true; reason = 'TP atteint'; }

// SL (avec break-even éventuel)
if (!shouldClose) {
  if (isBuy && currentPrice <= effectiveSlPrice) { shouldClose = true; reason = breakEvenTriggered ? 'Break-even BUY' : 'SL touche'; }
  else if (!isBuy && currentPrice >= effectiveSlPrice) { shouldClose = true; reason = breakEvenTriggered ? 'Break-even SELL' : 'SL touche'; }
}

// Zombie timeout
if (!shouldClose) {
  const rawTime = pos.entry_time;
  const isoTime = rawTime.toString().replace(' ', 'T').replace(/(\.(\d{3}))\d*$/, '$1') + 'Z';
  const entryTimeMs = new Date(isoTime).getTime();
  const diffMinutes = (Date.now() - entryTimeMs) / 60000;
  if (!isNaN(entryTimeMs) && diffMinutes > 45) {
    shouldClose = true;
    reason = 'Zombie timeout 45min';
  }
}

return [{ json: {
  shouldClose,
  reason,
  currentPrice,
  entryPrice,
  tpPrice,
  slPrice: effectiveSlPrice,
  breakEvenTriggered,
  direction,
  orderId: pos.order_id,
  quantity: pos.quantity,
  positionId: pos.id,
  mfe_pct: pos.mfe_pct || 0,
  mae_pct: pos.mae_pct || 0,
  status: shouldClose ? 'CLOSE_TRIGGERED' : 'MONITORING',
  variationPct: parseFloat(variationPct.toFixed(4))
} }];

