};

const entity = d.entity || '';
// Utiliser _sheet existant si entity absent (données déjà parsées)
const sn = sm[entity] || d._sheet || entity;

if (!sn) return [];
if (d.action === 'delete') return [];
if (!d.id) return [];

if (d.action === 'batch_upsert' && Array.isArray(d.rows)) {
  return d.rows.map(function(r) {
