}

const row = d.row || d;
const clean = Object.assign({}, row);
['_sheet','_action','_id','_batch','entity','action'].forEach(k => delete clean[k]);
clean._sheet = sn;
return [{ json: clean }];

// Générer le nom de l'onglet backup avec la date du jour
const today = new Date();
const pad = n => String(n).padStart(2,'0');
const dateStr = today.getFullYear() + '-' + pad(today.getMonth()+1) + '-' + pad(today.getDate());

