});

const items = $input.all();
if (!items || items.length === 0) return [{ json: { ema9_1h: 0, ema26_1h: 0, trendUp: false, trendDown: false } }];
const closes = items.map(c => parseFloat(c.json.close));
const ema = (data, period) => { const k = 2 / (period + 1); let v = data[0]; for (let i = 1; i < data.length; i++) v = data[i] * k + v * (1 - k); return v; };
const ema9_1h = ema(closes, 9);
const ema26_1h = ema(closes, 26);
return [{ json: { ema9_1h: parseFloat(ema9_1h.toFixed(2)), ema26_1h: parseFloat(ema26_1h.toFixed(2)), trendUp: ema9_1h > ema26_1h, trendDown: ema9_1h < ema26_1h } }];

const candles = $input.all();
return candles.map(candle => {
  const kline = candle.json;
  return { json: { openTime: parseFloat(kline[0]), open: parseFloat(kline[1]), high: parseFloat(kline[2]), low: parseFloat(kline[3]), close: parseFloat(kline[4]), volume: parseFloat(kline[7]) } };
});

const items = $input.all();
if (!items || items.length === 0) return [{ json: { error: 'No 5M data', prix_actuel: 0, rsi_14: 50, atr: 0, atrPercent: 0, ema9: 0 } }];
const closes = items.map(i => parseFloat(i.json.close));
const highs = items.map(i => parseFloat(i.json.high));
const lows = items.map(i => parseFloat(i.json.low));
const currentPrice = closes[closes.length - 1];
const emaCalc = (data, period) => { if (data.length < period) return data[data.length-1]; const k = 2/(period+1); let v = data[0]; for (let i=1;i<data.length;i++) v=data[i]*k+v*(1-k); return v; };
const rsiCalc = (closes, period=14) => { if (closes.length < period+1) return 50; let gains=0,losses=0; for (let i=1;i<=period;i++) { const c=closes[closes.length-i]-closes[closes.length-i-1]; if(c>0) gains+=c; else losses+=Math.abs(c); } const ag=gains/period,al=losses/period; if(al===0) return ag>0?100:50; return 100-(100/(1+ag/al)); };
const atrCalc = (h,l,c,period=14) => { if (c.length<period+1) return 0; let trs=[]; for(let i=1;i<c.length;i++) trs.push(Math.max(h[i]-l[i],Math.abs(h[i]-c[i-1]),Math.abs(l[i]-c[i-1]))); return trs.slice(-period).reduce((a,b)=>a+b,0)/period; };
const ema9=emaCalc(closes,9); const rsi14=rsiCalc(closes,14); const atr=atrCalc(highs,lows,closes,14);
const atrPercent=currentPrice>0?(atr/currentPrice)*100:0;
return [{ json: { prix_actuel: parseFloat(currentPrice.toFixed(2)), ema9: parseFloat(ema9.toFixed(2)), rsi_14: parseFloat(rsi14.toFixed(2)), atr: parseFloat(atr.toFixed(2)), atrPercent: parseFloat(atrPercent.toFixed(4)), dataPoints: items.length } }];

// === RÉCUPÉRATION DES INDICATEURS ===
const inputs = $input.all();
let ind1h = null, ind5m = null;
for (const input of inputs) {
  const json = input.json;
  if (json.ema9_1h !== undefined) ind1h = json;
  if (json.prix_actuel !== undefined) ind5m = json;
}
if (!ind1h || !ind5m) return [];

// Récupération trend 4H
let ind4h = null;
for (const input of inputs) {
  const json = input.json;
  if (json.ema9_4h !== undefined) ind4h = json;
}
const trend4hUp = ind4h ? ind4h.trend4hUp : true; // fallback permissif si absent

// === FILTRE HORAIRE UTC ===
const heureUTC = new Date().getUTCHours();
const heuresBloquees = [0, 1, 2, 3, 4, 6, 11, 18, 21, 22, 23]; // v44.8 — H10 débloqué
if (heuresBloquees.includes(heureUTC)) {
  return [{
    json: {
      _logOnly: true,
      prix_actuel: ind5m.prix_actuel,
      ema9_5m: ind5m.ema9 || 0,
      ema9_1h: ind1h.ema9_1h || 0,
      ema26_1h: ind1h.ema26_1h || 0,
      rsi_14: ind5m.rsi_14 || 0,
      atr_percent: ind5m.atrPercent || 0,
      trend_1h: ind1h.trendUp ? 'UP' : (ind1h.trendDown ? 'DOWN' : 'NEUTRAL'),
      signal_detected: false,
      direction: null,
      blocked_reason: `heure_bloquee(H${heureUTC})`
    }
  }];
}

// === SEUILS ===
const RSI_OVERSOLD = 40;
const RSI_SHORT = 45;
const MIN_ATR_PCT = 0.10;

// === SEUILS SHADOW SELL (filtres renforcés) ===
//const RSI_SHORT_SHADOW = 60;    // RSI > 60 au lieu de 45
//const MIN_ATR_SHORT = 0.15;     // ATR > 0.15% au lieu de 0.10%

// Dans le node "Detect Entry Signal" du workflow Entry Detection
const RSI_SHORT_SHADOW = 65;     // au lieu de 60
const MIN_ATR_SHORT = 0.20;      // au lieu de 0.15

// === VARIABLES ===
const prixActuel = ind5m.prix_actuel;
const ema9_5m = ind5m.ema9;
const rsi = ind5m.rsi_14;
const atrPct = ind5m.atrPercent;
const trendUp = ind1h.trendUp;
const trendDown = ind1h.trendDown;

// === CONDITIONS LONG ===
const validLong =
  prixActuel > ema9_5m &&
  trendUp &&        // EMA9 > EMA26 sur 1H
  trend4hUp &&      // EMA9 > EMA26 sur 4H (filtre tendance majeure)
  rsi < RSI_OVERSOLD &&
  atrPct >= MIN_ATR_PCT;

// === CONDITIONS SHORT ===
// Désactivé en réel — R/R insuffisant (1.053 sur 27 trades)
// Shadow mode actif avec filtres renforcés pour accumulation données
const validShort = false;

// === SHADOW SELL — filtres renforcés pour test ===
const shadowSell =
  prixActuel < ema9_5m &&        // prix sous EMA9 5m
  trendDown &&                    // trend 1H baissière
  rsi > RSI_SHORT_SHADOW &&       // RSI > 60 (surachat en tendance baissière)
  atrPct >= MIN_ATR_SHORT;        // ATR > 0.15% (volatilité suffisante)

// === ANALYSE DES RAISONS DE BLOCAGE ===
let blockedReason = '';
if (!validLong && !validShort) {
  const reasons = [];
  if (!trendUp && !trendDown) {
    reasons.push('trend_neutre');
  } else if (trendDown) {
    if (shadowSell) {
      reasons.push('SELL_shadow(RR<1.5)');
    } else {
      reasons.push('SELL_desactive(RR<1.5)');
    }
  } else if (trendUp && !validLong) {
    if (!trend4hUp) reasons.push('trend_4h_baissier');
    if (rsi >= RSI_OVERSOLD) reasons.push(`rsi_trop_haut_long(${rsi.toFixed(1)})`);
    if (atrPct < MIN_ATR_PCT) reasons.push(`atr_faible(${atrPct.toFixed(4)}<${MIN_ATR_PCT})`);
    if (prixActuel <= ema9_5m) reasons.push('prix_sous_ema9');
  }
  blockedReason = reasons.join('|');
}

// === LOG DATA ===
const logData = {
  prix_actuel: prixActuel,
  ema9_5m,
  ema9_1h: ind1h.ema9_1h,
  ema26_1h: ind1h.ema26_1h,
  rsi_14: rsi,
  atr_percent: atrPct,
  trend_1h: trendUp ? 'UP' : (trendDown ? 'DOWN' : 'NEUTRAL'),
  signal_detected: validLong || validShort,
  direction: validLong ? 'BUY' : (validShort ? 'SELL' : null),
  blocked_reason: blockedReason,
  shadow_sell: shadowSell   // flag pour le node PostgreSQL shadow
};

// === SIGNAL ===
if (validLong || validShort) {
  return [{
    json: {
      ...logData,
      signal_long: validLong,
      signal_short: validShort,
      signalQuality: 'HIGH',
      timestamp: new Date().toISOString()
    }
  }];
}

// === LOG SEULEMENT ===
return [{
  json: {
    _logOnly: true,
    ...logData
  }
}];

const signal = $node['Merge Log Data'].json;
if (!signal || (!signal.signal_long && !signal.signal_short)) return [];

const direction = signal.signal_long ? 'BUY' : 'SELL';
const prix = parseFloat(signal.prix_actuel);
const atrPct = parseFloat(signal.atr_percent) || 0.15;

const FLOORS = {
  BUY:  { tp: 0.20, sl: 0.10, be: 0.10 },
  SELL: { tp: 0.08, sl: 0.15, be: 0.05 }
};

function applyFloor(val, floor) {
  return Math.max(parseFloat(val) || floor, floor);
}

const row = $node['Get Dynamic TPSL'].json;
let tpPct, slPct, bePct;
if (direction === 'BUY') {
  tpPct = applyFloor(row.tp_long, FLOORS.BUY.tp);
  slPct = applyFloor(row.sl_long, FLOORS.BUY.sl);
  bePct = applyFloor(row.be_long, FLOORS.BUY.be);
} else {
  tpPct = applyFloor(row.tp_sell, FLOORS.SELL.tp);
  slPct = applyFloor(row.sl_sell, FLOORS.SELL.sl);
  bePct = applyFloor(row.be_sell, FLOORS.SELL.be);
}

// === PALIERS ATR-BASED ===
// Palier 1 : 1×ATR → BE
// Palier 2 : 2×ATR → protège 1×ATR
// Palier 3 : 3×ATR → protège 2×ATR
const trail1 = parseFloat((atrPct * 1.0).toFixed(4));
const trail2 = parseFloat((atrPct * 2.0).toFixed(4));
const trail3 = parseFloat((atrPct * 3.0).toFixed(4));

console.log(`ATR:${atrPct.toFixed(4)}% Paliers: L1=${trail1}% L2=${trail2}% L3=${trail3}%`);
console.log(`Percentiles [${direction}] TP:${tpPct.toFixed(4)}% SL:${slPct.toFixed(4)}% BE:${bePct.toFixed(4)}%`);

const tpPrice = direction === 'BUY'
  ? parseFloat((prix*(1+tpPct/100)).toFixed(2))
  : parseFloat((prix*(1-tpPct/100)).toFixed(2));
const slPrice = direction === 'BUY'
  ? parseFloat((prix*(1-slPct/100)).toFixed(2))
  : parseFloat((prix*(1+slPct/100)).toFixed(2));
const bePrice = direction === 'BUY'
  ? parseFloat((prix*(1+bePct/100)).toFixed(2))
  : parseFloat((prix*(1-bePct/100)).toFixed(2));

return [{ json: {
  direction, entry_price: prix,
  tp_price: tpPrice, sl_price: slPrice, be_price: bePrice,
  tp_pct: parseFloat(tpPct.toFixed(4)),
  sl_pct: parseFloat(slPct.toFixed(4)),
  be_pct: parseFloat(bePct.toFixed(4)),
  atr_pct: atrPct,
  trail1_pct: trail1,
  trail2_pct: trail2,
  trail3_pct: trail3,
  signalQuality: signal.signalQuality,
  rsi_14: signal.rsi_14, atr_percent: signal.atr_percent
} }];

// === PARAMÈTRES UTILISATEUR ===
const riskPct = 0.01; // 0.005 = 0.5%, 0.01 = 1%, 0.02 = 2%

// === RÉCUPÉRATION DU CAPITAL DEPUIS POSTGRESQL ===
const capitalRow = $node['Get Capital (PostgreSQL)'].json;
const capital = capitalRow && capitalRow.capital ? parseFloat(capitalRow.capital) : 25;
console.log('Capital lu depuis PostgreSQL:', capital);

// === RÉCUPÉRATION DES PRIX ===
const entry = parseFloat($node['Prepare Entry Order'].json.entry_price);
const sl = parseFloat($node['Prepare Entry Order'].json.sl_price);
if (!entry || !sl) throw new Error('entry_price ou sl_price manquant.');

// === CALCUL DISTANCE SL ===
const slDistance = Math.abs(entry - sl);
if (slDistance <= 0) throw new Error('Distance SL invalide.');

// === CALCUL RISQUE MAX ===
const maxLoss = capital * riskPct;

// === CALCUL QUANTITÉ BTC ===
let qty = maxLoss / slDistance;
if (!isFinite(qty) || qty <= 0) throw new Error('Quantité calculée invalide.');

// === ARRONDI 3 DÉCIMALES (Binance Futures BTCUSDT) ===
qty = Math.floor(qty * 1000) / 1000;

// === MINIMUM BINANCE FUTURES : notional >= $100 ===
const minQty = Math.ceil((100 / entry) * 1000) / 1000;
if (qty < minQty) {
  console.log('Quantité ajustée au minimum Binance: ' + qty + ' -> ' + minQty);
  qty = minQty;
}

// === CALCUL LEVIER ===
const positionValue = qty * entry;
let leverage = positionValue / capital;
if (leverage < 1) leverage = 1;
if (leverage > 10) leverage = 10;
leverage = Math.ceil(leverage);

// === LOGS ===
console.log('=== POSITION SIZING ===');
console.log('Capital :', capital);
console.log('Risque (%) :', riskPct * 100);
console.log('Perte max autorisée :', maxLoss);
