function ema(d,p){const k=2/(p+1);let e=d[0];for(let i=1;i<d.length;i++)e=d[i]*k+e*(1-k);return e;}
const e9_15=ema(c15,9);
const e26_15=ema(c15,26);
function rsi(d,p){let g=0,l=0;for(let i=d.length-p;i<d.length;i++){const diff=d[i]-d[i-1];if(diff>0)g+=diff;else l-=diff;}const rs=g/(l||0.0001);return 100-100/(1+rs);}
const rsi14=rsi(c15,14);
