    headers: { 'X-MBX-APIKEY': apiKey }
  }, null);
  console.log('Order detail:', JSON.stringify(orderDetail));
  exitPrice = parseFloat(orderDetail.avgPrice || '0');
}
if (exitPrice === 0) exitPrice = currentPrice;

// Calcul P&L
