const result = $input.first().json;
if (!result || !result.order_id) {
  return [];
}
return [{
  json: {
    id: result.id,
    order_id: result.order_id,
    direction: result.direction,
    entry_price: parseFloat(result.entry_price),
    tp_price: parseFloat(result.tp_price),
    sl_price: parseFloat(result.sl_price),
    be_price: parseFloat(result.be_price) || null,
    quantity: parseFloat(result.quantity),
    entry_time: result.entry_time instanceof Date 
    ? result.entry_time.toISOString() 
    : String(result.entry_time).replace(' ', 'T') + 'Z',
    mfe_pct: parseFloat(result.mfe_pct) || 0,
    mae_pct: parseFloat(result.mae_pct) || 0
  }
}];

const pos = $node['Check if Position Exists'].json;
const priceData = $input.first().json;
if (!pos || !pos.order_id) return [];

const currentPrice = parseFloat(priceData.price);
const entryPrice = pos.entry_price;
const tpPrice = pos.tp_price;
let slPrice = pos.sl_price;
const direction = pos.direction;
const isBuy = direction === 'BUY' || direction === 'LONG';

const variationPct = isBuy
  ? ((currentPrice - entryPrice) / entryPrice) * 100
  : ((entryPrice - currentPrice) / entryPrice) * 100;

// ATR et paliers stockés à l'entrée
const atrPct = parseFloat(pos.atr_pct) || 0.15;
const trail1 = atrPct * 1.0;
const trail2 = atrPct * 2.0;
const trail3 = atrPct * 3.0;

// === TRAILING STOP ATR-BASED ===
let trailingTriggered = false;
let trailingLevel = 0;
let newSlPrice = slPrice;

if (isBuy) {
  const gainPct = ((currentPrice - entryPrice) / entryPrice) * 100;
  if (gainPct >= trail3) {
    const p = parseFloat((entryPrice * (1 + trail2/100)).toFixed(2));
    if (p > newSlPrice) { newSlPrice = p; trailingTriggered = true; trailingLevel = 3; }
  } else if (gainPct >= trail2) {
    const p = parseFloat((entryPrice * (1 + trail1/100)).toFixed(2));
    if (p > newSlPrice) { newSlPrice = p; trailingTriggered = true; trailingLevel = 2; }
  } else if (gainPct >= trail1) {
    const p = parseFloat((entryPrice * 1.0002).toFixed(2));
    if (p > newSlPrice) { newSlPrice = p; trailingTriggered = true; trailingLevel = 1; }
  }
} else {
  const gainPct = ((entryPrice - currentPrice) / entryPrice) * 100;
  if (gainPct >= trail3) {
    const p = parseFloat((entryPrice * (1 - trail2/100)).toFixed(2));
    if (p < newSlPrice) { newSlPrice = p; trailingTriggered = true; trailingLevel = 3; }
  } else if (gainPct >= trail2) {
    const p = parseFloat((entryPrice * (1 - trail1/100)).toFixed(2));
    if (p < newSlPrice) { newSlPrice = p; trailingTriggered = true; trailingLevel = 2; }
  } else if (gainPct >= trail1) {
    const p = parseFloat((entryPrice * 0.9998).toFixed(2));
    if (p < newSlPrice) { newSlPrice = p; trailingTriggered = true; trailingLevel = 1; }
  }
}

// === SL PROGRESSIF (time-based) ===
// Après 15min sans mouvement > ±0.05% : réduire SL de 50%
// Après 30min sans mouvement > ±0.05% : fermer au marché
let slProgressif = false;
let slProgressifReason = '';
const entryTimeMs = new Date(pos.entry_time).getTime();
const diffMinutes = (Date.now() - entryTimeMs) / 60000;
const absVariation = Math.abs(variationPct);

if (!trailingTriggered) {
  if (diffMinutes >= 30 && absVariation <= 0.05) {
    slProgressif = true;
    slProgressifReason = 'SL progressif 30min';
  } else if (diffMinutes >= 15 && absVariation <= 0.05) {
    // Réduire SL de 50% vers l'entrée
    if (isBuy) {
      const reducedSl = parseFloat((slPrice + (entryPrice - slPrice) * 0.5).toFixed(2));
      if (reducedSl > newSlPrice) { newSlPrice = reducedSl; }
    } else {
      const reducedSl = parseFloat((slPrice - (slPrice - entryPrice) * 0.5).toFixed(2));
      if (reducedSl < newSlPrice) { newSlPrice = reducedSl; }
    }
  }
}

const effectiveSlPrice = newSlPrice;
let shouldClose = false;
let reason = '';

if (isBuy && currentPrice >= tpPrice) { shouldClose = true; reason = 'TP atteint'; }
else if (!isBuy && currentPrice <= tpPrice) { shouldClose = true; reason = 'TP atteint'; }

if (!shouldClose && slProgressif) {
  shouldClose = true;
  reason = slProgressifReason;
}

if (!shouldClose) {
  if (isBuy && currentPrice <= effectiveSlPrice) {
    shouldClose = true;
    reason = trailingTriggered ? 'Trailing ATR L' + trailingLevel : 'SL touche';
  } else if (!isBuy && currentPrice >= effectiveSlPrice) {
    shouldClose = true;
    reason = trailingTriggered ? 'Trailing ATR L' + trailingLevel : 'SL touche';
  }
}

// Zombie timeout 45min (sécurité)
if (!shouldClose) {
  if (!isNaN(entryTimeMs) && diffMinutes > 240) {
    shouldClose = true;
    reason = 'Zombie timeout 45min';
  }
}

return [{ json: {
  shouldClose, reason, currentPrice, entryPrice, tpPrice,
  slPrice: effectiveSlPrice, breakEvenTriggered: trailingTriggered,
  trailingLevel, atrPct, trail1, trail2, trail3,
  direction, orderId: pos.order_id, quantity: pos.quantity,
  positionId: pos.id, mfe_pct: pos.mfe_pct || 0, mae_pct: pos.mae_pct || 0,
  status: shouldClose ? 'CLOSE_TRIGGERED' : 'MONITORING',
  variationPct: parseFloat(variationPct.toFixed(4)),
  diffMinutes: parseFloat(diffMinutes.toFixed(1))
} }];

const crypto = require('crypto');
const https = require('https');
const exitData = $input.first().json;
const apiKey = '2UN0G8IDaUck5FqjWNK7dNSmYXwb6U2WqmDUkErlzrdbAAu4Nso2E5e3t9OKrRLP';
const secret = '2GtnvLGVpJ4NMz6Qpz7nANK4rg1FlzSON5f7L18pVR9RcesRu1MfxYBQhZXR0KV3';
const baseHost = 'demo-fapi.binance.com';
const entryPrice = parseFloat(exitData.entryPrice);
const currentPrice = parseFloat(exitData.currentPrice);
const quantity = parseFloat(exitData.quantity);
const direction = exitData.direction;
const closeSide = (direction === 'BUY' || direction === 'LONG') ? 'SELL' : 'BUY';
const qty = (Math.floor(quantity * 1000) / 1000).toFixed(3);

const makeRequest = (options, body) => new Promise((resolve) => {
  let responseData = '';
  const req = https.request(options, (res) => {
    res.on('data', (chunk) => { responseData += chunk; });
    res.on('end', () => {
      try { resolve(JSON.parse(responseData)); }
      catch(e) { resolve({ error: responseData }); }
    });
  });
  req.on('error', (e) => resolve({ error: e.message }));
  if (body) req.write(body);
  req.end();
});

// Étape 1 — Placer l'ordre
const timestamp1 = Date.now();
const params = 'symbol=BTCUSDC&side=' + closeSide + '&type=MARKET&quantity=' + qty + '&reduceOnly=true&timestamp=' + timestamp1;
const signature1 = crypto.createHmac('sha256', secret).update(params).digest('hex');
const body = params + '&signature=' + signature1;
const closeOrderResult = await makeRequest({
  hostname: baseHost, path: '/fapi/v1/order', method: 'POST',
  headers: {
    'X-MBX-APIKEY': apiKey,
    'Content-Type': 'application/x-www-form-urlencoded',
    'Content-Length': Buffer.byteLength(body)
  }
}, body);
console.log('Close order result:', JSON.stringify(closeOrderResult));

// Étape 2 — Récupérer le prix réel si avgPrice = 0
let exitPrice = parseFloat(closeOrderResult.avgPrice || '0');
if (exitPrice === 0 && closeOrderResult.orderId) {
  await new Promise(r => setTimeout(r, 500)); // attendre 500ms
  const orderId = closeOrderResult.orderId;
  const timestamp2 = Date.now();
  const qParams = 'symbol=BTCUSDC&orderId=' + orderId + '&timestamp=' + timestamp2;
  const signature2 = crypto.createHmac('sha256', secret).update(qParams).digest('hex');
  const orderDetail = await makeRequest({
    hostname: baseHost,
    path: '/fapi/v1/order?' + qParams + '&signature=' + signature2,
    method: 'GET',
    headers: { 'X-MBX-APIKEY': apiKey }
  }, null);
  console.log('Order detail:', JSON.stringify(orderDetail));
  exitPrice = parseFloat(orderDetail.avgPrice || '0');
}
if (exitPrice === 0) exitPrice = currentPrice;

// Calcul P&L
let pnlAmount = 0;
if (direction === 'BUY' || direction === 'LONG') {
  pnlAmount = (exitPrice - entryPrice) * quantity;
} else {
  pnlAmount = (entryPrice - exitPrice) * quantity;
}
const pnlPercent = direction === 'BUY'
  ? ((exitPrice - entryPrice) / entryPrice) * 100
  : ((entryPrice - exitPrice) / entryPrice) * 100;

return [{
  json: {
    mfe_pct: exitData.mfe_pct || 0,
    mae_pct: exitData.mae_pct || 0,
    orderId: exitData.orderId,
    closeOrderId: closeOrderResult.orderId || null,
    closeOrderError: closeOrderResult.error || closeOrderResult.msg || null,
    positionId: exitData.positionId,
    direction: direction,
    closeSide: closeSide,
    entryPrice: entryPrice,
    exitPrice: exitPrice,
    quantity: quantity,
    pnlAmount: parseFloat(pnlAmount.toFixed(2)),
    pnlPercent: parseFloat(pnlPercent.toFixed(4)),
    reason: exitData.reason,
    status: 'CLOSED',
    timestamp: new Date().toISOString()
  }
}];

const exitData = $node['Execute Exit Order'].json;

// Le capital sera mis à jour via PostgreSQL (nœud suivant)
// On passe juste les données nécessaires
