const https = require('https');
async function fetchKlines(interval, limit) {
  return new Promise((resolve, reject) => {
    const url = `https://fapi.binance.com/fapi/v1/klines?symbol=BTCUSDC&interval=${interval}&limit=${limit}`;
    https.get(url, (res) => {
      let data = '';
      res.on('data', chunk => data += chunk);
      res.on('end', () => resolve(JSON.parse(data)));
    }).on('error', reject);
  });
}

// Récupère 100 bougies 1H pour S&R et CHoCH (au lieu de 50)
const [k15, k1h] = await Promise.all([fetchKlines('15m', 50), fetchKlines('1h', 100)]);
if (!k15.length || !k1h.length) return [];

const c15 = k15.map(k => parseFloat(k[4]));
const h15 = k15.map(k => parseFloat(k[2]));
const l15 = k15.map(k => parseFloat(k[3]));
const v15 = k15.map(k => parseFloat(k[5]));
const prix = c15[c15.length - 1];

// === INDICATEURS DE BASE ===
function ema(d, p) { const k = 2/(p+1); let e = d[0]; for (let i=1;i<d.length;i++) e=d[i]*k+e*(1-k); return e; }
function rsi(d, p) { let g=0,l=0; for (let i=d.length-p;i<d.length;i++) { const diff=d[i]-d[i-1]; if(diff>0) g+=diff; else l-=diff; } return 100-100/(1+(g/(l||0.0001))); }
function atr(h,l,c,p) { let s=0; for (let i=h.length-p;i<h.length;i++) { const tr=Math.max(h[i]-l[i],Math.abs(h[i]-c[i-1]),Math.abs(l[i]-c[i-1])); s+=tr; } return (s/p/prix)*100; }

const e9_15=ema(c15,9), e26_15=ema(c15,26), rsi14=rsi(c15,14), atrPct=atr(h15,l15,c15,14);
const high20=Math.max(...h15.slice(-21,-1)), low20=Math.min(...l15.slice(-21,-1));
const vMoy=v15.slice(-21,-1).reduce((a,b)=>a+b,0)/20, vNow=v15[v15.length-1], volRatio=vNow/vMoy;

const h1h = k1h.map(k => parseFloat(k[2]));
const l1h = k1h.map(k => parseFloat(k[3]));
const c1h = k1h.map(k => parseFloat(k[4]));
const e9_1h=ema(c1h,9), e26_1h=ema(c1h,26), trend=e9_1h>e26_1h?'UP':'DOWN';

// === SUPPORT & RÉSISTANCE 1H ===
// Remplace la section S&R dans le code existant
// VERSION CORRIGÉE

function detectSR(highs, lows, strength=2) {
  const levels = [];
  const n = highs.length;
  for (let i = strength; i < n - strength; i++) {
    let isHigh = true, isLow = true;
    for (let j = 1; j <= strength; j++) {
      if (highs[i] <= highs[i-j] || highs[i] <= highs[i+j]) isHigh = false;
      if (lows[i]  >= lows[i-j]  || lows[i]  >= lows[i+j])  isLow  = false;
    }
    if (isHigh) levels.push({ price: highs[i], type: 'resistance' });
    if (isLow)  levels.push({ price: lows[i],  type: 'support'    });
  }

  // Merge niveaux proches ±0.3%
  const merged = [];
  const used = new Set();
  for (let i = 0; i < levels.length; i++) {
    if (used.has(i)) continue;
    const group = [levels[i]];
    for (let j = i+1; j < levels.length; j++) {
      if (!used.has(j) && Math.abs(levels[i].price - levels[j].price) / levels[i].price < 0.003) {
        group.push(levels[j]);
        used.add(j);
      }
    }
    used.add(i);
    merged.push({
      price: group.reduce((s,l) => s+l.price, 0) / group.length,
      type: levels[i].type,
      touches: group.length
    });
  }
  return merged;
}

const srLevels = detectSR(h1h, l1h);

// Sépare résistances (au-dessus) et supports (en dessous)
const resistances = srLevels
  .filter(l => l.price > prix)
  .sort((a,b) => a.price - b.price); // la plus basse en premier = la plus proche

const supports = srLevels
  .filter(l => l.price < prix)
  .sort((a,b) => b.price - a.price); // la plus haute en premier = la plus proche

const nearestResistance = resistances[0] || null;
const nearestSupport    = supports[0]    || null;

// Distance en %
const distRes = nearestResistance ? Math.abs(nearestResistance.price - prix) / prix * 100 : 999;
const distSup = nearestSupport    ? Math.abs(nearestSupport.price    - prix) / prix * 100 : 999;

// Trop proche = moins de 0.5%
const nearResistance = distRes < 0.5;
const nearSupport    = distSup < 0.5;


// === CHoCH (Change of Character) ===
// Sur 1H : détecte si la structure de marché a changé
function detectChoch1h(highs, lows, closes) {
  const n = closes.length;
  // Cherche les derniers swing highs et lows sur 1H (force 3)
  const swings = [];
  for (let i = 3; i < n - 3; i++) {
    let isHigh = true, isLow = true;
    for (let j = 1; j <= 3; j++) {
      if (highs[i] <= highs[i-j] || highs[i] <= highs[i+j]) isHigh = false;
      if (lows[i] >= lows[i-j] || lows[i] >= lows[i+j]) isLow = false;
    }
    if (isHigh) swings.push({ type: 'high', price: highs[i], index: i });
    if (isLow)  swings.push({ type: 'low',  price: lows[i],  index: i });
  }

  if (swings.length < 4) return { choch_bullish_1h: false, choch_bearish_1h: false };

  // Derniers swings
  const recent = swings.slice(-6);
  const lastHigh = recent.filter(s => s.type === 'high').slice(-1)[0];
  const lastLow  = recent.filter(s => s.type === 'low').slice(-1)[0];
  const prevHigh = recent.filter(s => s.type === 'high').slice(-2)[0];
  const prevLow  = recent.filter(s => s.type === 'low').slice(-2)[0];

  const currentPrice = closes[n-1];

  // CHoCH Bearish 1H : prix casse un lower high récent (structure baissière)
  const choch_bearish_1h = lastHigh && prevHigh &&
    lastHigh.price < prevHigh.price && // lower high formé
    currentPrice < lastLow?.price;     // prix sous le dernier low

  // CHoCH Bullish 1H : prix casse un higher low récent (structure haussière)
  const choch_bullish_1h = lastLow && prevLow &&
    lastLow.price > prevLow.price &&   // higher low formé
    currentPrice > lastHigh?.price;    // prix au-dessus du dernier high

  return {
    choch_bearish_1h: !!choch_bearish_1h,
    choch_bullish_1h: !!choch_bullish_1h,
    last_swing_high_1h: lastHigh?.price || null,
    last_swing_low_1h: lastLow?.price || null
  };
}

// CHoCH sur 15m
function detectChoch15m(highs, lows, closes) {
  const n = closes.length;
  const swings = [];
  for (let i = 2; i < n - 2; i++) {
    let isHigh = true, isLow = true;
    for (let j = 1; j <= 2; j++) {
      if (highs[i] <= highs[i-j] || highs[i] <= highs[i+j]) isHigh = false;
      if (lows[i] >= lows[i-j] || lows[i] >= lows[i+j]) isLow = false;
    }
    if (isHigh) swings.push({ type: 'high', price: highs[i], index: i });
    if (isLow)  swings.push({ type: 'low',  price: lows[i],  index: i });
  }

  if (swings.length < 4) return { choch_bullish_15m: false, choch_bearish_15m: false };

  const recent = swings.slice(-6);
  const lastHigh = recent.filter(s => s.type === 'high').slice(-1)[0];
  const lastLow  = recent.filter(s => s.type === 'low').slice(-1)[0];
  const prevHigh = recent.filter(s => s.type === 'high').slice(-2)[0];
  const prevLow  = recent.filter(s => s.type === 'low').slice(-2)[0];
  const currentPrice = closes[n-1];

  const choch_bearish_15m = lastHigh && prevHigh &&
    lastHigh.price < prevHigh.price &&
    currentPrice < lastLow?.price;

  const choch_bullish_15m = lastLow && prevLow &&
    lastLow.price > prevLow.price &&
    currentPrice > lastHigh?.price;

  return {
    choch_bearish_15m: !!choch_bearish_15m,
    choch_bullish_15m: !!choch_bullish_15m
  };
}

const choch1h  = detectChoch1h(h1h, l1h, c1h);
const choch15m = detectChoch15m(h15, l15, c15);

// CHoCH combiné : 15m déclenche + 1H confirme
const choch_sell_confirmed = choch15m.choch_bearish_15m && choch1h.choch_bearish_1h;
const choch_buy_confirmed  = choch15m.choch_bullish_15m && choch1h.choch_bullish_1h;

// === SIGNAUX FINAUX ===
const hUTC=new Date().getUTCHours(), hBloq=[0,1,2,3,4,6,11], heureOk=!hBloq.includes(hUTC), volOk=volRatio>1.2;

// MODE OBSERVATION : conditions originales inchangées
