const buyOk  = prix>high20 && e9_15>e26_15 && trend==='UP'   && rsi14>=50 && rsi14<=75 && heureOk && volOk;
const sellOk = prix<low20  && e9_15<e26_15 && trend==='DOWN' && rsi14>=25 && rsi14<=50 && heureOk && volOk;

