function parseYahoo(data) {
  const r = data.chart.result[0];
  const q = r.indicators.quote[0];
  const ts = r.timestamp;
  const out = [];
  for (let i = 0; i < ts.length; i++) {
    if (q.close[i] == null) continue;
    out.push({ t: ts[i], o: q.open[i], h: q.high[i], l: q.low[i], c: q.close[i], v: q.volume[i] || 0 });
  }
  return out;
}

const k15 = parseYahoo($node['Get 15m Klines'].json);
const k1h  = parseYahoo($node['Get 1H Klines'].json);
if (!k15.length || !k1h.length) return [];

const c15=k15.map(k=>k.c), h15=k15.map(k=>k.h), l15=k15.map(k=>k.l), v15=k15.map(k=>k.v);
const prix = c15[c15.length-1];

function ema(d,p){const k=2/(p+1);let e=d[0];for(let i=1;i<d.length;i++)e=d[i]*k+e*(1-k);return e;}
function rsi(d,p){let g=0,l=0;for(let i=d.length-p;i<d.length;i++){const diff=d[i]-d[i-1];if(diff>0)g+=diff;else l-=diff;}return 100-100/(1+(g/(l||0.0001)));}
function atr(h,l,c,p){let s=0;for(let i=h.length-p;i<h.length;i++){const tr=Math.max(h[i]-l[i],Math.abs(h[i]-c[i-1]),Math.abs(l[i]-c[i-1]));s+=tr;}return(s/p/prix)*100;}

const e9_15=ema(c15,9),e26_15=ema(c15,26),rsi14=rsi(c15,14),atrPct=atr(h15,l15,c15,14);
const high20=Math.max(...h15.slice(-21,-1)),low20=Math.min(...l15.slice(-21,-1));
const vMoy=v15.slice(-21,-1).reduce((a,b)=>a+b,0)/20,vNow=v15[v15.length-1],volRatio=vMoy>0?vNow/vMoy:1;

const h1h=k1h.map(k=>k.h),l1h=k1h.map(k=>k.l),c1h=k1h.map(k=>k.c);
const e9_1h=ema(c1h,9),e26_1h=ema(c1h,26),trend=e9_1h>e26_1h?'UP':'DOWN';

function detectSR(highs,lows,strength=2){
  const levels=[];const n=highs.length;
  for(let i=strength;i<n-strength;i++){
    let isHigh=true,isLow=true;
    for(let j=1;j<=strength;j++){
      if(highs[i]<=highs[i-j]||highs[i]<=highs[i+j])isHigh=false;
      if(lows[i]>=lows[i-j]||lows[i]>=lows[i+j])isLow=false;
    }
    if(isHigh)levels.push({price:highs[i],type:'resistance'});
    if(isLow)levels.push({price:lows[i],type:'support'});
  }
  const merged=[],used=new Set();
  for(let i=0;i<levels.length;i++){
    if(used.has(i))continue;
    const group=[levels[i]];
    for(let j=i+1;j<levels.length;j++){
      if(!used.has(j)&&Math.abs(levels[i].price-levels[j].price)/levels[i].price<0.003){group.push(levels[j]);used.add(j);}
    }
    used.add(i);
    merged.push({price:group.reduce((s,l)=>s+l.price,0)/group.length,type:levels[i].type,touches:group.length});
  }
  return merged;
}

const srLevels=detectSR(h1h,l1h);
const resistances=srLevels.filter(l=>l.price>prix).sort((a,b)=>a.price-b.price);
const supports=srLevels.filter(l=>l.price<prix).sort((a,b)=>b.price-a.price);
const nearestResistance=resistances[0]||null,nearestSupport=supports[0]||null;
const distRes=nearestResistance?Math.abs(nearestResistance.price-prix)/prix*100:999;
const distSup=nearestSupport?Math.abs(nearestSupport.price-prix)/prix*100:999;
const nearResistance=distRes<0.5,nearSupport=distSup<0.5;

function detectChoch1h(highs,lows,closes){
  const n=closes.length,swings=[];
  for(let i=3;i<n-3;i++){
    let isHigh=true,isLow=true;
    for(let j=1;j<=3;j++){if(highs[i]<=highs[i-j]||highs[i]<=highs[i+j])isHigh=false;if(lows[i]>=lows[i-j]||lows[i]>=lows[i+j])isLow=false;}
    if(isHigh)swings.push({type:'high',price:highs[i],index:i});
    if(isLow)swings.push({type:'low',price:lows[i],index:i});
  }
  if(swings.length<4)return{choch_bullish_1h:false,choch_bearish_1h:false};
  const recent=swings.slice(-6);
  const lastHigh=recent.filter(s=>s.type==='high').slice(-1)[0],lastLow=recent.filter(s=>s.type==='low').slice(-1)[0];
  const prevHigh=recent.filter(s=>s.type==='high').slice(-2)[0],prevLow=recent.filter(s=>s.type==='low').slice(-2)[0];
  const cp=closes[n-1];
  return{
    choch_bearish_1h:!!(lastHigh&&prevHigh&&lastHigh.price<prevHigh.price&&cp<lastLow?.price),
    choch_bullish_1h:!!(lastLow&&prevLow&&lastLow.price>prevLow.price&&cp>lastHigh?.price),
    last_swing_high_1h:lastHigh?.price||null,last_swing_low_1h:lastLow?.price||null
  };
}

function detectChoch15m(highs,lows,closes){
  const n=closes.length,swings=[];
  for(let i=2;i<n-2;i++){
    let isHigh=true,isLow=true;
    for(let j=1;j<=2;j++){if(highs[i]<=highs[i-j]||highs[i]<=highs[i+j])isHigh=false;if(lows[i]>=lows[i-j]||lows[i]>=lows[i+j])isLow=false;}
    if(isHigh)swings.push({type:'high',price:highs[i]});
    if(isLow)swings.push({type:'low',price:lows[i]});
  }
  if(swings.length<4)return{choch_bullish_15m:false,choch_bearish_15m:false};
  const recent=swings.slice(-6);
  const lastHigh=recent.filter(s=>s.type==='high').slice(-1)[0],lastLow=recent.filter(s=>s.type==='low').slice(-1)[0];
  const prevHigh=recent.filter(s=>s.type==='high').slice(-2)[0],prevLow=recent.filter(s=>s.type==='low').slice(-2)[0];
  const cp=closes[n-1];
  return{
    choch_bearish_15m:!!(lastHigh&&prevHigh&&lastHigh.price<prevHigh.price&&cp<lastLow?.price),
    choch_bullish_15m:!!(lastLow&&prevLow&&lastLow.price>prevLow.price&&cp>lastHigh?.price)
  };
}

const choch1h=detectChoch1h(h1h,l1h,c1h),choch15m=detectChoch15m(h15,l15,c15);
const choch_sell_confirmed=choch15m.choch_bearish_15m&&choch1h.choch_bearish_1h;
const choch_buy_confirmed=choch15m.choch_bullish_15m&&choch1h.choch_bullish_1h;

const hUTC=new Date().getUTCHours();
const hBloq=[0,1,2,3,4,5,6,22,23];
const heureOk=!hBloq.includes(hUTC);
const atrOk=atrPct>0.05;
const volOk=volRatio>1.2;

const buyOk=prix>high20&&e9_15>e26_15&&trend==='UP'&&rsi14>=50&&rsi14<=75&&heureOk&&volOk&&atrOk;
const sellOk=prix<low20&&e9_15<e26_15&&trend==='DOWN'&&rsi14>=25&&rsi14<=50&&heureOk&&volOk&&atrOk;
const signalOk=buyOk||sellOk;
const direction=buyOk?'BUY':sellOk?'SELL':null;

const reasons=[];
if(!heureOk)reasons.push('heure_bloquee(H'+hUTC+')');
else{
  if(!atrOk)reasons.push('atr_faible('+atrPct.toFixed(3)+'%)');
  if(!signalOk){
    if(prix<=high20&&prix>=low20)reasons.push('pas_breakout');
    if(buyOk&&nearResistance)reasons.push('near_resistance('+nearestResistance.price.toFixed(0)+')');
    if(sellOk&&nearSupport)reasons.push('near_support('+nearestSupport.price.toFixed(0)+')');
  }
}

return[{json:{
  signal_detected:signalOk,direction,prix_actuel:prix,symbole:'XAUUSD',
  ema9_15m:e9_15,ema26_15m:e26_15,rsi_14:rsi14,atr_percent:atrPct,
  highest20:high20,lowest20:low20,breakout_buy:prix>high20,breakout_sell:prix<low20,
  vol_ratio:volRatio,trend_1h:trend,heure_utc:hUTC,
  sr_resistance:nearestResistance?.price||null,sr_support:nearestSupport?.price||null,
  sr_near_resistance:nearResistance,sr_near_support:nearSupport,
  choch_bearish_1h:choch1h.choch_bearish_1h,choch_bullish_1h:choch1h.choch_bullish_1h,
  choch_bearish_15m:choch15m.choch_bearish_15m,choch_bullish_15m:choch15m.choch_bullish_15m,
  choch_sell_confirmed,choch_buy_confirmed,
  last_swing_high_1h:choch1h.last_swing_high_1h,last_swing_low_1h:choch1h.last_swing_low_1h,
  blocked_reason:reasons.join('|'),timestamp:new Date().toISOString()
}}];

const sig = $node['Detect Entry Signal'].json;
const siz = $node['Calculate Position Size'].json;

if (!sig.signal_detected || !sig.direction) return [];

const prix   = sig.prix_actuel;
const atrPct = sig.atr_percent;
const dir    = sig.direction;

const tpPct = Math.max(atrPct * 2.0, 0.20);
const slPct = Math.max(atrPct * 1.0, 0.12);
const bePct = Math.max(atrPct * 0.8, 0.10);

let tp_price, sl_price, be_price;
if (dir === 'BUY') {
  tp_price = parseFloat((prix * (1 + tpPct / 100)).toFixed(2));
  sl_price = parseFloat((prix * (1 - slPct / 100)).toFixed(2));
  be_price = parseFloat((prix * (1 + bePct / 100)).toFixed(2));
} else {
  tp_price = parseFloat((prix * (1 - tpPct / 100)).toFixed(2));
  sl_price = parseFloat((prix * (1 + slPct / 100)).toFixed(2));
  be_price = parseFloat((prix * (1 - bePct / 100)).toFixed(2));
}

return [{
  json: {
    direction:      dir,
    entry_price:    prix,
    tp_price, sl_price, be_price,
    tp_pct:         parseFloat(tpPct.toFixed(4)),
    sl_pct:         parseFloat(slPct.toFixed(4)),
    be_pct:         parseFloat(bePct.toFixed(4)),
    atr_pct:        atrPct,
    atr_percent:    atrPct,
    rsi_14:         sig.rsi_14,
    breakout_level: dir === 'BUY' ? sig.highest20 : sig.lowest20,
    breakout_high:  sig.highest20,
    breakout_low:   sig.lowest20,
    trend_1h:       sig.trend_1h,
    vol_ratio:      sig.vol_ratio,
    quantity:       siz.quantity,
    montantUSDT:    siz.montantUSDT,
    leverage:       siz.leverage,
    maxLossUSD:     siz.maxLossUSD,
    capital:        siz.capital,
    riskPct:        siz.riskPct
  }
}];

const order=$input.first().json;
const orderId='SIM_GOLD_'+Date.now();
return[{json:{...order,direction:order.direction,orderId,executedPrice:order.entry_price,executedQty:order.quantity}}];

const result = $input.first().json;
if (!result || !result.order_id) {
  return [];
}
return [{
  json: {
    id: result.id,
    order_id: result.order_id,
    direction: result.direction,
    entry_price: parseFloat(result.entry_price),
    tp_price: parseFloat(result.tp_price),
    sl_price: parseFloat(result.sl_price),
    be_price: parseFloat(result.be_price) || null,
    quantity: parseFloat(result.quantity),
    entry_time: result.entry_time instanceof Date 
    ? result.entry_time.toISOString() 
    : String(result.entry_time).replace(' ', 'T') + 'Z',
    mfe_pct: parseFloat(result.mfe_pct) || 0,
    mae_pct: parseFloat(result.mae_pct) || 0
  }
}];

const pos = $node['Check if Position Exists'].json;
const priceData = $input.first().json;
if (!pos || !pos.order_id) return [];

// Parse Yahoo Finance format
let currentPrice;
try {
  const q = priceData.chart.result[0].indicators.quote[0];
  const closes = q.close.filter(c => c != null);
  currentPrice = closes[closes.length - 1];
} catch(e) {
  return [];
}
const entryPrice = pos.entry_price;
const tpPrice = pos.tp_price;
let slPrice = pos.sl_price;
const direction = pos.direction;
const isBuy = direction === 'BUY' || direction === 'LONG';

const variationPct = isBuy
  ? ((currentPrice - entryPrice) / entryPrice) * 100
  : ((entryPrice - currentPrice) / entryPrice) * 100;

// ATR et paliers stockés à l'entrée
const atrPct = parseFloat(pos.atr_pct) || 0.15;
const trail1 = atrPct * 1.0;
const trail2 = atrPct * 2.0;
const trail3 = atrPct * 3.0;

// === TRAILING STOP ATR-BASED ===
let trailingTriggered = false;
let trailingLevel = 0;
let newSlPrice = slPrice;

if (isBuy) {
  const gainPct = ((currentPrice - entryPrice) / entryPrice) * 100;
  if (gainPct >= trail3) {
    const p = parseFloat((entryPrice * (1 + trail2/100)).toFixed(2));
    if (p > newSlPrice) { newSlPrice = p; trailingTriggered = true; trailingLevel = 3; }
  } else if (gainPct >= trail2) {
    const p = parseFloat((entryPrice * (1 + trail1/100)).toFixed(2));
    if (p > newSlPrice) { newSlPrice = p; trailingTriggered = true; trailingLevel = 2; }
  } else if (gainPct >= trail1) {
    const p = parseFloat((entryPrice * 1.0002).toFixed(2));
    if (p > newSlPrice) { newSlPrice = p; trailingTriggered = true; trailingLevel = 1; }
  }
} else {
  const gainPct = ((entryPrice - currentPrice) / entryPrice) * 100;
  if (gainPct >= trail3) {
    const p = parseFloat((entryPrice * (1 - trail2/100)).toFixed(2));
    if (p < newSlPrice) { newSlPrice = p; trailingTriggered = true; trailingLevel = 3; }
  } else if (gainPct >= trail2) {
    const p = parseFloat((entryPrice * (1 - trail1/100)).toFixed(2));
    if (p < newSlPrice) { newSlPrice = p; trailingTriggered = true; trailingLevel = 2; }
  } else if (gainPct >= trail1) {
    const p = parseFloat((entryPrice * 0.9998).toFixed(2));
    if (p < newSlPrice) { newSlPrice = p; trailingTriggered = true; trailingLevel = 1; }
  }
}

// === SL PROGRESSIF (time-based) ===
// Après 15min sans mouvement > ±0.05% : réduire SL de 50%
// Après 30min sans mouvement > ±0.05% : fermer au marché
let slProgressif = false;
let slProgressifReason = '';
const entryTimeMs = new Date(pos.entry_time).getTime();
const diffMinutes = (Date.now() - entryTimeMs) / 60000;
const absVariation = Math.abs(variationPct);

if (!trailingTriggered) {
  if (diffMinutes >= 30 && absVariation <= 0.05) {
    slProgressif = true;
    slProgressifReason = 'SL progressif 30min';
  } else if (diffMinutes >= 15 && absVariation <= 0.05) {
    // Réduire SL de 50% vers l'entrée
    if (isBuy) {
      const reducedSl = parseFloat((slPrice + (entryPrice - slPrice) * 0.5).toFixed(2));
      if (reducedSl > newSlPrice) { newSlPrice = reducedSl; }
    } else {
      const reducedSl = parseFloat((slPrice - (slPrice - entryPrice) * 0.5).toFixed(2));
      if (reducedSl < newSlPrice) { newSlPrice = reducedSl; }
    }
  }
}

const effectiveSlPrice = newSlPrice;
let shouldClose = false;
let reason = '';

if (isBuy && currentPrice >= tpPrice) { shouldClose = true; reason = 'TP atteint'; }
else if (!isBuy && currentPrice <= tpPrice) { shouldClose = true; reason = 'TP atteint'; }

if (!shouldClose && slProgressif) {
  shouldClose = true;
  reason = slProgressifReason;
}

if (!shouldClose) {
  if (isBuy && currentPrice <= effectiveSlPrice) {
    shouldClose = true;
    reason = trailingTriggered ? 'Trailing ATR L' + trailingLevel : 'SL touche';
  } else if (!isBuy && currentPrice >= effectiveSlPrice) {
    shouldClose = true;
    reason = trailingTriggered ? 'Trailing ATR L' + trailingLevel : 'SL touche';
  }
}

// Zombie timeout 45min (sécurité)
if (!shouldClose) {
  if (!isNaN(entryTimeMs) && diffMinutes > 240) {
    shouldClose = true;
    reason = 'Zombie timeout 45min';
  }
}

return [{ json: {
  shouldClose, reason, currentPrice, entryPrice, tpPrice,
  slPrice: effectiveSlPrice, breakEvenTriggered: trailingTriggered,
  trailingLevel, atrPct, trail1, trail2, trail3,
  direction, orderId: pos.order_id, quantity: pos.quantity,
  positionId: pos.id, mfe_pct: pos.mfe_pct || 0, mae_pct: pos.mae_pct || 0,
  status: shouldClose ? 'CLOSE_TRIGGERED' : 'MONITORING',
  variationPct: parseFloat(variationPct.toFixed(4)),
  diffMinutes: parseFloat(diffMinutes.toFixed(1))
} }];

