const https = require('https');
const exitData = $input.first().json;
const apiKey = '2UN0G8IDaUck5FqjWNK7dNSmYXwb6U2WqmDUkErlzrdbAAu4Nso2E5e3t9OKrRLP';
const secret = '2GtnvLGVpJ4NMz6Qpz7nANK4rg1FlzSON5f7L18pVR9RcesRu1MfxYBQhZXR0KV3';
