const capital = $input.first().json;
const capitalInitial = parseFloat(capital.capital_initial);
const capitalActuel  = parseFloat(capital.capital_actuel);
const dailyPnl       = parseFloat(capital.daily_pnl_pct || 0);
const consLosses     = parseInt(capital.consecutive_losses || 0);
const currentRisk    = parseFloat(capital.risk_pct_current);

const variation = ((capitalActuel - capitalInitial) / capitalInitial) * 100;

let newRisk = 0.01;
if (variation >= 4)       newRisk = 0.02;
else if (variation >= 2)  newRisk = 0.015;
else if (variation >= 0)  newRisk = 0.01;
else if (variation >= -2) newRisk = 0.005;
else if (variation >= -4) newRisk = 0.0025;
else                      newRisk = 0;

// AVANT
//let botStatus = 'ACTIVE';
// APRÈS — lit le statut actuel et ne le change que si circuit breaker
let botStatus = capital.bot_status; // garde le statut existant
let action = 'NORMAL';
let reason = '';

if (dailyPnl <= -3.5) {
  botStatus = 'PAUSE';
  action = 'CIRCUIT_BREAKER';
  reason = 'Daily loss limit atteinte (-3.5%)';
} else if (newRisk === 0) {
  botStatus = 'PAUSE';
  action = 'PAUSE_DRAWDOWN';
  reason = 'Drawdown > 6% - pause requise';
} else if (newRisk !== currentRisk) {
  action = 'RISK_ADJUSTED';
  reason = `Risque ajuste de ${(currentRisk*100).toFixed(2)}% a ${(newRisk*100).toFixed(2)}%`;
}

return [{ json: {
  capital_actuel:   capitalActuel,
  capital_initial:  capitalInitial,
  variation_pct:    parseFloat(variation.toFixed(3)),
  daily_pnl_pct:    dailyPnl,
  risk_pct_before:  currentRisk,
  risk_pct_after:   newRisk,
  bot_status:       botStatus,
  action:           action,
  reason:           reason,
  consecutive_losses: consLosses
} }];

// Récupère les données depuis Calculate Risk (pas Update Capital qui ne propage rien)
const r = $('Calculate Risk').first().json;
return [{ json: r }];

const r = $('Calculate Risk').first().json;
let emoji = '⚠️';
if (r.action === 'CIRCUIT_BREAKER') emoji = '🛑';
if (r.action === 'PAUSE_DRAWDOWN')  emoji = '🔴';
if (r.action === 'RISK_ADJUSTED')   emoji = '📊';
const msg = `${emoji} Risk Manager SMC\n`
  + `Action: ${r.action}\n`
  + `${r.reason}\n`
  + `Capital: ${r.capital_actuel}€\n`
  + `Variation: ${r.variation_pct}%\n`
  + `Daily PnL: ${r.daily_pnl_pct}%\n`
  + `Risque: ${(r.risk_pct_after*100).toFixed(2)}%`;
return [{ json: { message: msg, action: r.action } }];

