const capitalInit = parseFloat(capital.capital_initial).toFixed(2);
const capitalNow  = parseFloat(capital.capital_actuel).toFixed(2);
const variation   = ((capitalNow - capitalInit) / capitalInit * 100).toFixed(2);
const dailyPnl    = parseFloat(capital.daily_pnl_pct || 0).toFixed(3);
const riskPct     = (parseFloat(capital.risk_pct_current) * 100).toFixed(2);

const totalSignals = parseInt(signals.total_signals || 0);
const executed     = parseInt(signals.executed || 0);
const expired      = parseInt(signals.expired || 0);
