const currentPrice = parseFloat(price.close || 0).toFixed(5);

const pnlEmoji   = parseFloat(totalPnl) >= 0 ? '🟢' : '🔴';
const biasEmoji  = structure?.bias === 'BULLISH' ? '🟢' : structure?.bias === 'BEARISH' ? '🔴' : '⚪';
const varEmoji   = parseFloat(variation) >= 0 ? '📈' : '📉';

const date = new Date().toLocaleDateString('fr-FR', { timeZone: 'Europe/Paris', day: '2-digit', month: '2-digit', year: 'numeric' });

const msg = `📊 *RAPPORT SMC — EURUSD — ${date}*\n`
