  + `  Daily PnL : ${parseFloat(dailyPnl) >= 0 ? '+' : ''}${dailyPnl}%\n`
  + `  Risque    : ${riskPct}%/trade\n`
  + `━━━━━━━━━━━━━━━━━━━━\n`
  + `📈 *TRADES DU JOUR*\n`
  + `  Total   : ${totalTrades}\n`
  + `  ✅ Wins  : ${wins}\n`
  + `  ❌ Losses: ${losses}\n`
  + `  WinRate : ${winRate}%\n`
  + `  ${pnlEmoji} PnL    : ${parseFloat(totalPnl) >= 0 ? '+' : ''}${totalPnl}€\n`
  + (totalTrades > 0 ? `  Avg Win  : +${avgWin}€\n  Avg Loss : ${avgLoss}€\n` : '')
  + `━━━━━━━━━━━━━━━━━━━━\n`
  + `🎯 *SIGNAUX DU JOUR*\n`
  + `  Générés  : ${totalSignals}\n`
